function ragContext(q){try{if(!attachedText)return '';const norm=s=>String(s).toLocaleLowerCase('tr-TR').normalize('NFD').replace(/[\u0300-\u036f]/g,'');const terms=norm(q).match(/[\p{L}\p{N}]{3,}/gu)||[];const chunks=attachedText.split(/\n\s*\n/).flatMap(p=>p.length>900?p.match(/[\s\S]{1,850}(?:\s|$)/g)||[p]:[p]);return chunks.map((c,i)=>({c,i,score:terms.reduce((n,t)=>n+(norm(c).includes(t)?1:0),0)})).sort((a,b)=>b.score-a.score||a.i-b.i).slice(0,5).map(x=>x.c).join('\n\n').slice(0,7000)}catch(e){return attachedText.slice(0,4000)}}
function localAnswer(q){
 const raw=String(q||'').trim(),t=raw.toLocaleLowerCase('tr-TR'),ctx=ragContext(raw);
 const time=()=>{try{return new Intl.DateTimeFormat('tr-TR',{timeZone:'Europe/Istanbul',dateStyle:'full',timeStyle:'short'}).format(new Date())+' (Europe/Istanbul, UTC+3)'}catch(e){return 'Cihazın yerel saati'}};
 if(/(sen kimsin|neler yapabilirsin|what are you|who are you|what can you do)/i.test(t))return '<h2>Ben gemini.AI.upgreaded</h2><p>Türkçe ve İngilizce yanıt veren; açıklama, çeviri, özet, kod, planlama ve oyun tasarımı çalışmalarında yardımcı olan bir tarayıcı asistanıyım. Gemini API anahtarı varsa modelden yanıt alırım; dosya eklediğinizde ilgili bölümleri bağlam olarak kullanırım.</p>';
 if(/(saat kaç|tarih|bugün|current time|date today|today)/i.test(t))return '<h2>İstanbul’da şimdi</h2><p><b>'+esc(time())+'</b></p>';
 if(/(çevir|tercüme|translate)/i.test(t)){let m=raw.match(/[“"']([^”"']+)[”"']\s*(?:→|to|into|-)\s*([\p{L} ]+)/iu)||raw.match(/(?:çevir|translate)\s+(.+?)\s+(?:to|into|→)\s+([\p{L} ]+)/iu);if(m)return '<h2>Çeviri</h2><p><b>'+esc(m[1].trim())+'</b> → <b>'+esc(m[2].trim())+'</b></p><p>Bu çevrimdışı sürüm hedef dilde güvenilir bir çeviri motoru kullanmıyor. Gemini bağlantısı varsa yeniden deneyin; yoksa hedef dili belirterek çeviriyi başka bir çeviri aracıyla doğrulayın.</p>';return '<h2>Çeviri için metin ve hedef dil gerekli</h2><p>Örnek: “Good morning” → Türkçe.</p>'}
 if(/(merhaba|selam|hello|^hi\b)/i.test(t))return '<h2>Merhaba!</h2><p>Sorunu veya üzerinde çalıştığınız konuyu yazın; doğrudan yanıtlamaya çalışayım.</p>';
 if(ctx)return '<h2>Ekli dosyadan ilgili bağlam</h2><blockquote>'+esc(ctx.slice(0,5000)).replace(/\n/g,'<br>')+'</blockquote><p><small>Bu alıntı ekli dosyadan alınmıştır; tek başına doğrulanmış dış kaynak değildir. Gemini yanıtı alınamadığı için içerik hakkında çıkarım uydurmuyorum.</small></p>';
 if(/(nasıl çalışır|how does|how .* work|çalışma prensibi)/i.test(t))return '<h2>Bu soruyu yanıtlamak için konuya özgü bilgi gerekiyor</h2><p>Gemini bağlantısı şu anda yanıt vermedi. Konunun adını koruyarak yeniden deneyin; bağlantı yokken genel bir süreç şablonunu gerçek açıklama gibi sunmayacağım.</p>';
 if(/(kim icat etti|icat eden|who invented|who discovered)/i.test(t))return '<h2>İcat sorusu</h2><p>İcatlarda öncül çalışmalar, patent sahibi ve çalışan ürünü geliştiren kişi farklı olabilir. Gemini veya kaynak erişimi olmadan kişi ve tarih atfetmek güvenilir olmaz. İcat adını yeniden deneyin; model eriştiğinde katkıları ve belirsizlikleri ayrı sunarım.</p>';
 if(/(listele|list|top \d|en iyi|ranking|sıralama)/i.test(t))return '<h2>Güvenilir liste için kapsam önemli</h2><p>Ölçüt (ör. tarih, bütçe, performans) ve kapsamı belirtin. Çevrimdışı modda güncel sıralama veya kaynaklı liste uydurmuyorum.</p>';
 if(/(özet|summar|study guide|ders not)/i.test(t))return '<h2>Özetlenecek içerik gerekli</h2><p>Metni buraya yapıştırın veya <b>＋</b> ile desteklenen bir dosya ekleyin. İçerik olmadan konuya özel özet ya da sınav bilgisi uydurmam.</p>';
 return '<h2>Şu anda güvenilir yanıt üretemiyorum</h2><p>Gemini erişimi yok ve bu tarayıcıdaki çevrimdışı bilgi sınırlı. API anahtarını Studio’dan ekleyip tekrar deneyebilir veya ilgili metin/dosyayı paylaşabilirsiniz. Ham servis hataları gösterilmeden yerel bağlam kullanılabilir.</p>';
}

