function shouldSearch(query){
  const q=normText(query);
  if(!q)return false;
  // Do not search for conversation, creative fiction, general reasoning, or questions already answered by the supplied context.
  if(/\b(hikaye|hikaye yaz|senaryo|kurgu|creative|fiction|story|poem|siir|sohbet|chat|genel mantik|genel mantık|acikla|anlat|neden|nasıl|nasil)\b/i.test(q)&&!/\b(haber|guncel|son durum|bugun|dun|bu hafta|gecen hafta|fiyat|hava durumu|borsa|score|skor|surum|version|release|kaynak|dogrula|doğrula|araştır|araştırma|ara|google|kontrol et)\b/i.test(q))return false;
  const explicit=/\b(arastir|arastirma|araştır|araştırma|google'da bul|google da bul|kontrol et|kaynak getir|kaynaklar|get source|sources|find online|search the web|look up)\b/i.test(q);
  const changing=/\b(guncel|son durum|haber|news|latest|current|today|today's|now|recent|release|surum|version|fiyat|price|weather|hava durumu|borsa|stock|skor|score|202[0-9]|bugun|dun|yarin|bu hafta|gecen hafta|su an|son dakika|teknik dokuman|technical documentation|api docs|documentation|dokumantasyon)\b/i.test(q);
  const timeSensitive=/what(?:'s| is) the date|what day is it|what time is it|current time|bugun ayin kaci|bugun tarih ne|hangi gun|saat kac|saat su an kac/i.test(q);
  return explicit||changing||timeSensitive;
}
function buildSearchQuery(query){
  const q=String(query||'').replace(/\s+/g,' ').trim();
  if(!q)return '';
  let out=q
    .replace(/^(lütfen\s+|lutfen\s+|please\s+|can you\s+|could you\s+)/i,'')
    .replace(/\b(arastir|araştır|araştırma|google'da bul|google da bul|kontrol et|kaynak getir|search the web|look up|get sources?)\b/gi,'')
    .replace(/[?!.]+$/,'')
    .replace(/\s+/g,' ').trim();
  const tokens=out.split(/\s+/).filter(Boolean);
  if(tokens.length>12)out=tokens.slice(0,12).join(' ');
  return out.slice(0,500);
}

