.shell: .shell{height:100%;display:grid;grid-template-columns:280px 1fr}

.main: .main{min-width:0;height:100%;display:flex;flex-direction:column;position:relative}

.topbar: .topbar{height:64px;display:flex;align-items:center;justify-content:space-between;padding:0 24px;border-bottom:1px solid transparent}

.chat: .chat-list{overflow:auto}

.hero: .hero{height:calc(100vh - 210px);min-height:390px;display:flex;flex-direction:column;justify-content:center}

.composer-wrap: .composer-wrap{padding:10px 24px 18px}

.composer-box: .composer-box{max-width:780px;margin:auto;border:1px solid var(--line);border-radius:20px;background:white;box-shadow:var(--shadow);padding:8px}

.mode-row: .mode-row{height:30px;display:flex;align-items:center;padding:0 4px;gap:5px}

.mode-row button: .mode-row button{border:0;background:transparent;border-radius:7px;padding:5px 8px;color:#777;font-size:12px}

.input-row: .input-row{display:flex;align-items:flex-end}

.add-btn: .add-btn{width:38px;height:38px;border:0;border-radius:12px;background:#f2f2ef;font-size:20px;color:#555}

.send-btn: .send-btn{width:38px;height:38px;border:0;border-radius:12px;background:#222;color:white;font-size:18px}

@media(max-width:760px): @media(max-width:760px){body{overflow:hidden}

