113:     const get = (tag) => block.match(new RegExp(`<${tag}\\b[^>]*>([\\s\\S]*?)<\\/${tag}>`, 'i'))?.[1] || '';
114:     const title = cleanText(get('title'));
115:     const url = validHttpUrl(cleanText(get('link')));
116:     if (!title || !url) continue;
117:     const sourceMatch = title.match(/\s+-\s+([^]+)$/);
118:     const source = cleanText(sourceMatch?.[1] || 'Google News');
119:     const headline = cleanText(sourceMatch ? title.slice(0, sourceMatch.index).trim() : title);
120:     items.push({
121:       title: headline.slice(0, 300),
122:       url,
123:       snippet: cleanText(get('description') || headline).slice(0, 1200),
124:       source,
125:       date: cleanText(get('pubDate')).slice(0, 100),
126:     });
127:     if (items.length >= count) break;
128:   }
129:   return items;
130: }
131: 
132: async function fetchWithTimeout(operation, timeoutMs = SOURCE_TIMEOUT_MS) {
133:   const controller = new AbortController();
134:   const timeout = setTimeout(() => controller.abort(), timeoutMs);
135:   try {
136:     return await operation(controller.signal);
137:   } finally {
138:     clearTimeout(timeout);
139:   }
140: }
