142: module.exports = async function handler(req, res) {
143:   const ping = req.query && req.query.ping === '1';
144:   const pingFromUrl = typeof req.url === 'string' && /(?:[?&])ping=1(?:&|$)/.test(req.url);
145:   if (ping || pingFromUrl) {
146:     return res.status(200).json({ ok: true, commit: 'ping-test', node: process.version });
147:   }
148: 
149:   if (req.method !== 'POST' && req.method !== 'GET') {
150:     res.set('Allow', 'GET, POST');
151:     return reply(res, 405, { error: 'Only GET and POST are supported.' });
152:   }
153: 
154:   let body = req.body;
155:   if (req.method === 'GET') {
156:     const queryParams = req.query || {};
157:     let query = queryParams.q ?? queryParams.query;
158:     if (query === undefined && typeof req.url === 'string') {
159:       try {
160:         const url = new URL(req.url, 'http://localhost');
161:         query = url.searchParams.get('q') ?? url.searchParams.get('query');
162:       } catch {}
163:     }
164:     body = { query, count: queryParams.count };
165:   }
166:   if (typeof body === 'string') {
167:     try { body = JSON.parse(body); } catch { return reply(res, 400, { error: 'Geçersiz istek gövdesi.' }); }
168:   }
169:   const rawQuery = typeof body?.query === 'string' ? body.query.trim() : '';
170:   if (!rawQuery || rawQuery.length > MAX_QUERY_LENGTH) {
171:     return reply(res, 400, { error: 'Sorgu boş olamaz ve 500 karakteri aşamaz.' });
172:   }
173:   const count = Math.max(1, Math.min(MAX_RESULTS, Number.parseInt(body?.count, 10) || MAX_RESULTS));
174:   const query = buildMeaningfulQuery(rawQuery);
175: 
176:   const apiKey = process.env.GOOGLE_SEARCH_API_KEY;
177:   const cx = process.env.GOOGLE_SEARCH_CX;
178: 
179:   if (apiKey && cx) {
180:     try {
181:       const items = await fetchWithTimeout((signal) => {
182:         const params = new URLSearchParams({ key: apiKey, cx, q: query, num: String(count), hl: 'tr', gl: 'tr' });
183:         return fetch('https://www.googleapis.com/customsearch/v1?' + params.toString(), {
184:           method: 'GET', headers: { Accept: 'application/json', 'User-Agent': 'FoVerse-AI-Search/1.0' }, signal,
185:         }).then(async (response) => {
186:           if (!response.ok) throw new Error(`Google search failed: ${response.status}`);
187:           const data = await response.json();
188:           return (Array.isArray(data.items) ? data.items : []).slice(0, count).map((item) => {
189:             const url = validHttpUrl(item.link);
190:             let source = cleanText(item.displayLink);
191:             try { if (!source) source = cleanText(new URL(url).hostname); } catch {}
192:             return {
193:               title: cleanText(item.title || 'Kaynak').slice(0, 300), url,
194:               snippet: cleanText(item.snippet || '').slice(0, 1200), source,
195:               date: cleanText(item.pagemap?.metatags?.[0]?.['article:published_time'] || item.pagemap?.metatags?.[0]?.date || '').slice(0, 100),
196:             };
197:           }).filter((item) => item.url);
198:         });
199:       });
200:       const normalized = dedupeAndSort(items).slice(0, count);
201:       if (normalized.length) return reply(res, 200, { items: normalized, source: 'google', query });
202:     } catch (_) {
203:       // Fall through to keyless Google News RSS.
204:     }
205:   }
206: 
207:   try {
208:     const items = await fetchWithTimeout((signal) => {
209:       const params = new URLSearchParams({ q: query, hl: 'tr', gl: 'TR', ceid: 'TR:tr' });
210:       return fetch('https://news.google.com/rss/search?' + params.toString(), {
211:         method: 'GET', headers: { Accept: 'application/rss+xml, application/xml;q=0.9, text/xml;q=0.8', 'User-Agent': 'FoVerse-AI-Search/1.0' }, signal,
212:       }).then(async (response) => {
213:         if (!response.ok) throw new Error(`Google News RSS failed: ${response.status}`);
214:         return rssSearchResult(await response.text(), count);
215:       });
216:     });
217:     const normalized = dedupeAndSort(items).slice(0, count);
218:     if (normalized.length) return reply(res, 200, { items: normalized, source: 'google_news_rss', query });
219:   } catch (_) {
220:     // Continue to the independent, keyless GDELT article API.
221:   }
222: 
223:   try {
224:     const items = await fetchWithTimeout((signal) => gdeltSearch(query, count, signal));
225:     const normalized = dedupeAndSort(items).slice(0, count);
226:     if (normalized.length) return reply(res, 200, { items: normalized, source: 'gdelt', query });
227:   } catch (_) {
228:     // Return a clean fallback only after all configured sources are exhausted.
229:   }
230: 
231:   return reply(res, 502, {
232:     error: 'Canlı web araması şu anda kullanılamıyor; haber kaynağına ve yedek arama katmanına ulaşılamadı.',
233:     code: 'LIVE_SEARCH_UNAVAILABLE',
234:   });
235: }
