237: function rssSearchResult(xml, count) {
238:   const items = [];
239:   const itemMatches = xml.match(/<item\b[^>]*>[\s\S]*?<\/item>/gi) || [];
240:   for (const block of itemMatches) {
241:     const get = (tag) => block.match(new RegExp(`<${tag}\\b[^>]*>([\\s\\S]*?)<\\/${tag}>`, 'i'))?.[1] || '';
242:     const title = cleanText(get('title'));
243:     const url = validHttpUrl(cleanText(get('link')));
244:     if (!title || !url) continue;
245:     const sourceMatch = title.match(/\s+-\s+([^]+)$/);
246:     const source = cleanText(sourceMatch?.[1] || 'Google News');
247:     const headline = cleanText(sourceMatch ? title.slice(0, sourceMatch.index).trim() : title);
248:     items.push({
249:       title: headline.slice(0, 300), url,
250:       snippet: cleanText(get('description') || headline).slice(0, 1200),
251:       source,
252:       date: cleanText(get('pubDate')).slice(0, 100),
253:     });
254:     if (items.length >= count) break;
255:   }
256:   return dedupeAndSort(items).slice(0, count);
257: }
