259: async function gdeltSearch(query, count, signal) {
260:   const params = new URLSearchParams({
261:     query,
262:     mode: 'ArtList',
263:     format: 'json',
264:     maxrecords: String(count),
265:     sort: 'HybridRel',
266:   });
267:   const response = await fetch(`https://api.gdeltproject.org/api/v2/doc/doc?${params}`, {
268:     method: 'GET',
269:     headers: { Accept: 'application/json', 'User-Agent': 'FoVerse-AI-Search/1.0' },
270:     signal,
271:   });
272:   if (!response.ok) throw new Error(`GDELT search failed: ${response.status}`);
273:   const data = await response.json();
274:   return (Array.isArray(data.articles) ? data.articles : []).slice(0, count).map((article) => {
275:     const url = validHttpUrl(article.url);
276:     let source = cleanText(article.domain);
277:     try { if (!source && url) source = cleanText(new URL(url).hostname); } catch {}
278:     return {
279:       title: cleanText(article.title || 'Kaynak').slice(0, 300),
280:       url,
281:       snippet: cleanText(article.snippet || '').slice(0, 1200),
282:       source: source.slice(0, 200),
283:       date: cleanText(article.seendate || article.datetime || '').slice(0, 100),
284:     };
285:   }).filter((item) => item.title && item.url);
286: }

