chatHistory.push({q,a:answer});
try{store.set('geminiHistory',JSON.stringify(chatHistory.slice(-20)))}catch(e){}}catch(e){try{$('searchStatus').classList.remove('show');
const inner=$('chatInner');
if(inner)inner.querySelectorAll('.typing').forEach(t=>t.parentElement?.parentElement?.remove())}catch(z){}}finally{$('searchStatus').classList.remove('show');
busy=false;
$('sendBtn').disabled=false;
abort=null}}

