function isNewsDetailRequest(query) {
  const normalized = normalize(query);
  return /\b(detay|detaylandir|detayli|ayrint|acikla|bilgi ver)\b/.test(normalized)
    && /\b(haber|madde|baslik|konu|bunun|bunu|bununla|hakkinda|icin)\b/.test(normalized);
