function resolveNumberedNewsFollowup(query){
  const q=String(query||'');
  const numberMatch=q.match(/(?:^|\b)([1-9]\d?)\.?\s*(?:haber(?:i|in|leri)?|madd(?:e|esi)|numaralı\s+haber)/i);
  const n=numberMatch?.[1]||null;
  if(!n&&!/(detaylandır|detayını|detaylı|o haber|bu haber|haber hakkında)/i.test(q))return '';
  const cards=[...document.querySelectorAll('#chatInner .message.ai')];
  for(let i=cards.length-1;i>=0;i--){
    const text=cards[i].innerText||cards[i].textContent||'';
    if(n){
      const found=text.match(new RegExp('(?:^|\\n\\s*)'+n+'\\.\\s*(.+)','i'));
      if(found)return found[1].replace(/<[^>]*>/g,' ').replace(/\\s+/g,' ').trim().slice(0,220);
    }
  }
  if(/bunun detayını|o haber|bu haber|haber hakkında/i.test(q)){
    for(let i=cards.length-1;i>=0;i--){
      const text=cards[i].innerText||cards[i].textContent||'';
      const found=text.match(/(?:^|\n)\s*1\.\s*(.+)/i);
      if(found)return found[1].replace(/<[^>]*>/g,' ').replace(/\s+/g,' ').trim().slice(0,220);
    }
  }
  return '';
}
function buildSearchQuery(query){
  const q=String(query||'').replace(/\s+/g,' ').trim();
  if(!q)return '';
  const newsQuery=window.FoVerseNewsIntent?.searchQuery(q);
  if(newsQuery)return newsQuery;

