  const numberMatch=q.match(/(?:^|\b)([1-9]\d?)\.?\s*(?:haber(?:i|in|leri)?|madd(?:e|esi)|numaralı\s+haber)/i);
  const n=numberMatch?.[1]||null;
  const detail=window.FoVerseNewsIntent?.isNewsDetailRequest(q);
  if(!n&&!detail)return '';
  const cards=[...document.querySelectorAll('#chatInner .message.ai')];
  if(n){
    for(let i=cards.length-1;i>=0;i--){
      const text=cards[i].innerText||cards[i].textContent||'';
      const lines=text.split(/\r?\n/);
      const found=lines.map(line=>line.match(new RegExp('^\\s*'+n+'[.)]\\s*(.+)$','i'))).find(Boolean);
      if(found)return found[1].replace(/<[^>]*>/g,' ').replace(/\s+/g,' ').trim().slice(0,220);
    }
  }
  if(detail)return window.FoVerseNewsIntent?.detailSearchQuery(q)||q;
  return '';
}
