187: function buildSearchQuery(query){
188:   const q=String(query||'').replace(/\s+/g,' ').trim();
189:   if(!q)return '';
190:   if(window.FoVerseNewsIntent?.isNewsDetailRequest(q))return window.FoVerseNewsIntent.detailSearchQuery(q)||q;
191:   const newsQuery=window.FoVerseNewsIntent?.searchQuery(q);
192:   if(newsQuery)return newsQuery;
193:   const normalized=q.toLocaleLowerCase('tr-TR').replace(/[?!.]+$/,'').trim();
194:   if(/^(gündemde ne var|gundemde ne var|gündem|gundem|günse|gunse|bugün neler oldu|bugun neler oldu|son gelişmeler|son gelismeler|haberler|güncel haberler|guncel haberler)$/.test(normalized))return 'Türkiye ve dünya gündem son dakika haberleri';
195:   let out=q
196:     .replace(/^(lütfen\s+|lutfen\s+|please\s+|can you\s+|could you\s+)/i,'')
197:     .replace(/\b(arastir|araştır|araştırma|google'da bul|google da bul|kontrol et|kaynak getir|search the web|look up|get sources?)\b/gi,'')
198:     .replace(/[?!.]+$/,'')
199:     .replace(/\s+/g,' ').trim();
200:   const tokens=out.split(/\s+/).filter(Boolean);
201:   if(tokens.length>12)out=tokens.slice(0,12).join(' ');
202:   return out.slice(0,500);
203: }
